package com.example.taketoday;
import com.example.taketoday.auth.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Import;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.mail.SimpleMailMessage;
import org.springframework.mail.javamail.JavaMailSenderImpl;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.web.context.WebApplicationContext;
import org.springframework.mock.web.MockHttpSession;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;
import static org.springframework.security.test.web.servlet.setup.SecurityMockMvcConfigurers.springSecurity;
import java.util.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:auth;MODE=PostgreSQL;DB_CLOSE_DELAY=-1","spring.datasource.username=sa","spring.datasource.password=","spring.datasource.driver-class-name=org.h2.Driver","app.admin-email=","app.admin-password="})
@Import(AuthIntegrationTests.MailConfig.class)
class AuthIntegrationTests {
 @TestConfiguration static class MailConfig { @Bean CapturingMail mail(){return new CapturingMail();} }
 static class CapturingMail extends JavaMailSenderImpl {String code;boolean fail;@Override public void send(SimpleMailMessage message){if(fail)throw new org.springframework.mail.MailSendException("test");code=message.getText().substring(9,15);} }
 @Autowired WebApplicationContext context;@Autowired JdbcTemplate db;@Autowired CapturingMail mail;
 MockMvc mvc;
 @BeforeEach void setup(){mvc=MockMvcBuilders.webAppContextSetup(context).apply(springSecurity()).build();db.update("DELETE FROM auth_challenges");db.update("DELETE FROM establishments");db.update("DELETE FROM accounts");db.update("DELETE FROM auth_throttle");mail.fail=false;}
 private String register(String role) throws Exception {return postJson("/api/auth/register","{\"email\":\"user@example.com\",\"password\":\"StrongPassword123\",\"name\":\"Покупатель\",\"role\":\""+role+"\",\"establishmentName\":\"Пекарня\",\"address\":\"Бишкек\",\"contact\":\"12345\",\"workingHours\":\"9–18\"}").andExpect(status().isOk()).andReturn().getResponse().getContentAsString();}
 private String id(String json){return json.split("\"challengeId\":\"")[1].split("\"")[0];}
 private ResultActions postJson(String url,String json)throws Exception{return mvc.perform(post(url).with(csrf()).contentType("application/json").content(json));}
 private ResultActions verify(String id,String code)throws Exception{return postJson("/api/auth/verify","{\"challengeId\":\""+id+"\",\"code\":\""+code+"\"}");}
 @Test void requiresEmailCodeAndPreventsReplay()throws Exception{String challenge=id(register("CUSTOMER"));mvc.perform(get("/api/customer/home")).andExpect(status().isUnauthorized());String code=mail.code;var result=verify(challenge,code).andExpect(status().isOk()).andExpect(jsonPath("$.role").value("CUSTOMER")).andReturn();var session=(MockHttpSession)result.getRequest().getSession(false);mvc.perform(get("/api/customer/home").session(session)).andExpect(status().isOk());mvc.perform(get("/api/staff/home").session(session)).andExpect(status().isForbidden());verify(challenge,code).andExpect(status().isBadRequest());}
 @Test void forbidsAdminRegistrationAndDuplicates()throws Exception{register("CUSTOMER");postJson("/api/auth/register","{\"email\":\"USER@example.com\",\"password\":\"StrongPassword123\",\"name\":\"User\",\"role\":\"CUSTOMER\"}").andExpect(status().isConflict());postJson("/api/auth/register","{\"email\":\"admin@example.com\",\"password\":\"StrongPassword123\",\"name\":\"User\",\"role\":\"ADMIN\"}").andExpect(status().isBadRequest());}
 @Test void limitsWrongCodesAndPasswordAttempts()throws Exception{String challenge=id(register("CUSTOMER"));String wrong="000000".equals(mail.code)?"000001":"000000";for(int i=0;i<5;i++)verify(challenge,wrong).andExpect(status().isBadRequest());verify(challenge,mail.code).andExpect(status().isBadRequest());for(int i=0;i<9;i++)postJson("/api/auth/login","{\"email\":\"user@example.com\",\"password\":\"WrongPassword\"}").andExpect(status().isUnauthorized());postJson("/api/auth/login","{\"email\":\"user@example.com\",\"password\":\"WrongPassword\"}").andExpect(status().isTooManyRequests());}
 @Test void expiresCodesAndChecksCsrf()throws Exception{String challenge=id(register("CUSTOMER"));db.update("UPDATE auth_challenges SET expires_at=?",java.sql.Timestamp.from(java.time.Instant.now().minusSeconds(1)));verify(challenge,mail.code).andExpect(status().isBadRequest());mvc.perform(post("/api/auth/login").contentType("application/json").content("{}")).andExpect(status().isForbidden());}
 @Test void isolatesStaffEstablishmentAndGuest()throws Exception{String challenge=id(register("STAFF"));var result=verify(challenge,mail.code).andExpect(status().isOk()).andReturn();var session=(MockHttpSession)result.getRequest().getSession(false);mvc.perform(get("/api/staff/home").session(session)).andExpect(status().isOk()).andExpect(jsonPath("$.name").value("Пекарня"));mvc.perform(get("/api/customer/home").session(session)).andExpect(status().isForbidden());mvc.perform(get("/api/auth/me")).andExpect(jsonPath("$.role").value("GUEST"));mvc.perform(post("/api/orders").with(csrf())).andExpect(status().isUnauthorized());}
 @Test void mailFailureRollsBackRegistration()throws Exception{mail.fail=true;postJson("/api/auth/register","{\"email\":\"user@example.com\",\"password\":\"StrongPassword123\",\"name\":\"User\",\"role\":\"CUSTOMER\"}").andExpect(status().isServiceUnavailable());assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM accounts",Integer.class));}
 @Test void resetsPasswordAndRevokesOldSession()throws Exception{String challenge=id(register("CUSTOMER"));var result=verify(challenge,mail.code).andExpect(status().isOk()).andReturn();var session=(MockHttpSession)result.getRequest().getSession(false);db.update("UPDATE auth_challenges SET sent_at=?",java.sql.Timestamp.from(java.time.Instant.now().minusSeconds(61)));String reset=id(postJson("/api/auth/forgot-password","{\"email\":\"user@example.com\"}").andExpect(status().isOk()).andReturn().getResponse().getContentAsString());postJson("/api/auth/reset-password","{\"challengeId\":\""+reset+"\",\"code\":\""+mail.code+"\",\"password\":\"NewPassword123\"}").andExpect(status().isOk());mvc.perform(get("/api/customer/home").session(session)).andExpect(status().isUnauthorized());postJson("/api/auth/login","{\"email\":\"user@example.com\",\"password\":\"StrongPassword123\"}").andExpect(status().isUnauthorized());}

 @Test void passwordAloneNeverAuthenticates()throws Exception{String first=id(register("CUSTOMER"));verify(first,mail.code).andExpect(status().isOk());db.update("UPDATE auth_challenges SET sent_at=?",java.sql.Timestamp.from(java.time.Instant.now().minusSeconds(61)));String login=id(postJson("/api/auth/login","{\"email\":\"user@example.com\",\"password\":\"StrongPassword123\"}").andExpect(status().isOk()).andReturn().getResponse().getContentAsString());mvc.perform(get("/api/auth/me")).andExpect(jsonPath("$.role").value("GUEST"));verify(login,mail.code).andExpect(status().isOk());}
 @Test void resendInvalidatesOldChallenge()throws Exception{String old=id(register("CUSTOMER"));String oldCode=mail.code;postJson("/api/auth/resend","{\"challengeId\":\""+old+"\"}").andExpect(status().isTooManyRequests());db.update("UPDATE auth_challenges SET sent_at=?",java.sql.Timestamp.from(java.time.Instant.now().minusSeconds(61)));String fresh=id(postJson("/api/auth/resend","{\"challengeId\":\""+old+"\"}").andExpect(status().isOk()).andReturn().getResponse().getContentAsString());verify(old,oldCode).andExpect(status().isBadRequest());verify(fresh,mail.code).andExpect(status().isOk());}
 @Test void logoutAndBlockRevokeAccess()throws Exception{String challenge=id(register("CUSTOMER"));var result=verify(challenge,mail.code).andExpect(status().isOk()).andReturn();var session=(MockHttpSession)result.getRequest().getSession(false);mvc.perform(post("/api/auth/logout").session(session).with(csrf())).andExpect(status().isNoContent());assertTrue(session.isInvalid());db.update("UPDATE auth_challenges SET sent_at=?",java.sql.Timestamp.from(java.time.Instant.now().minusSeconds(61)));String login=id(postJson("/api/auth/login","{\"email\":\"user@example.com\",\"password\":\"StrongPassword123\"}").andExpect(status().isOk()).andReturn().getResponse().getContentAsString());session=(MockHttpSession)verify(login,mail.code).andExpect(status().isOk()).andReturn().getRequest().getSession(false);db.update("UPDATE accounts SET blocked=TRUE");mvc.perform(get("/api/customer/home").session(session)).andExpect(status().isUnauthorized());}
}
